  <script>
    const filterButtons = Array.from(document.querySelectorAll('.filter-btn'));
    const products = Array.from(document.querySelectorAll('.product'));
    const searchInput = document.getElementById('searchInput');
    const wishlistButtons = Array.from(document.querySelectorAll('.wish'));
    const countdown = {
      days: document.getElementById('days'),
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds')
    };

    let activeFilter = 'all';

    function applyFilters() {
      const query = searchInput.value.trim().toLowerCase();
      products.forEach((product) => {
        const category = product.dataset.category;
        const name = product.dataset.name.toLowerCase();
        const matchesCategory = activeFilter === 'all' || category === activeFilter;
        const matchesQuery = !query || name.includes(query);
        product.hidden = !(matchesCategory && matchesQuery);
      });
    }

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => {
        activeFilter = button.dataset.filter;
        filterButtons.forEach((btn) => btn.setAttribute('aria-pressed', String(btn === button)));
        applyFilters();
      });
    });

    searchInput.addEventListener('input', applyFilters);

    wishlistButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const pressed = button.getAttribute('aria-pressed') === 'true';
        button.setAttribute('aria-pressed', String(!pressed));
        button.textContent = pressed ? '♡' : '♥';
      });
    });

    const releaseEnds = new Date();
    releaseEnds.setDate(releaseEnds.getDate() + 12);
    releaseEnds.setHours(releaseEnds.getHours() + 8, releaseEnds.getMinutes() + 24, releaseEnds.getSeconds() + 51, 0);

    function updateCountdown() {
      const remaining = Math.max(0, releaseEnds - new Date());
      const seconds = Math.floor(remaining / 1000);
      const days = Math.floor(seconds / 86400);
      const hours = Math.floor((seconds % 86400) / 3600);
      const minutes = Math.floor((seconds % 3600) / 60);
      const secs = seconds % 60;

      countdown.days.textContent = String(days).padStart(2, '0');
      countdown.hours.textContent = String(hours).padStart(2, '0');
      countdown.minutes.textContent = String(minutes).padStart(2, '0');
      countdown.seconds.textContent = String(secs).padStart(2, '0');
    }

    updateCountdown();
    setInterval(updateCountdown, 1000);
  </script>
